import React, { useState } from "react";
import "./index.css";

function App() {
  const [isSignUp, setIsSignUp] = useState(true);

  const days = Array.from({ length: 31 }, (_, i) => i + 1);

  const months = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  const currentYear = new Date().getFullYear();
  const years = [];
  for (let y = currentYear; y >= 1900; y--) {
    years.push(y);
  }

  const [formData, setFormData] = useState({
    firstName: "",
    surname: "",
    birthDay: "",
    birthMonth: "",
    birthYear: "",
    gender: "",
    emailOrMobile: "",
    password: ""
  });

  const [message, setMessage] = useState("");

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSignup = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:8081/api/auth/signup", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          firstName: formData.firstName,
          surname: formData.surname,
          birthDay: Number(formData.birthDay),
          birthMonth: formData.birthMonth,
          birthYear: Number(formData.birthYear),
          gender: formData.gender,
          emailOrMobile: formData.emailOrMobile,
          password: formData.password
        })
      });

      const result = await response.text();

      if (response.ok) {
        setMessage("Signup successful!");
        console.log(result);

        setFormData({
          firstName: "",
          surname: "",
          birthDay: "",
          birthMonth: "",
          birthYear: "",
          gender: "",
          emailOrMobile: "",
          password: ""
        });
      } else {
        setMessage(result);
      }
    } catch (error) {
      console.error("Signup error:", error);
      setMessage("Cannot connect to backend.");
    }
  };

  return (
    <div className="auth-page">
      <div className={`auth-container ${isSignUp ? "signup-mode" : ""}`}>
        <div className="auth-panel form-panel">
          {isSignUp ? (
            <div className="form-wrapper">
              <h2>SIGN UP</h2>
              <p className="form-subtext">Get started on RentMate</p>

              <form onSubmit={handleSignup}>
                <div className="row two-cols">
                  <div className="form-group">
                    <label>First Name</label>
                    <input
                      type="text"
                      name="firstName"
                      value={formData.firstName}
                      onChange={handleChange}
                      placeholder="First name"
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>Surname</label>
                    <input
                      type="text"
                      name="surname"
                      value={formData.surname}
                      onChange={handleChange}
                      placeholder="Surname"
                      required
                    />
                  </div>
                </div>

                <label className="section-label">Date of Birth</label>

                <div className="row three-cols">
                  <select
                    name="birthDay"
                    value={formData.birthDay}
                    onChange={handleChange}
                    required
                  >
                    <option value="">Day</option>
                    {days.map((day) => (
                      <option key={day} value={day}>{day}</option>
                    ))}
                  </select>

                  <select
                    name="birthMonth"
                    value={formData.birthMonth}
                    onChange={handleChange}
                    required
                  >
                    <option value="">Month</option>
                    {months.map((month, index) => (
                      <option key={index} value={month}>{month}</option>
                    ))}
                  </select>

                  <select
                    name="birthYear"
                    value={formData.birthYear}
                    onChange={handleChange}
                    required
                  >
                    <option value="">Year</option>
                    {years.map((year) => (
                      <option key={year} value={year}>{year}</option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Gender</label>
                  <select
                    name="gender"
                    value={formData.gender}
                    onChange={handleChange}
                    required
                  >
                    <option value="">Select your gender</option>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Prefer not to say">Prefer not to say</option>
                  </select>
                </div>

                <div className="form-group">
                  <label>Email or Mobile Number</label>
                  <input
                    type="text"
                    name="emailOrMobile"
                    value={formData.emailOrMobile}
                    onChange={handleChange}
                    placeholder="Enter Mobile Number or Email Address"
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Password</label>
                  <input
                    type="password"
                    name="password"
                    value={formData.password}
                    onChange={handleChange}
                    placeholder="Enter Password"
                    required
                  />
                </div>

                <button className="primary-btn" type="submit">
                  CREATE ACCOUNT
                </button>
              </form>

              {message && <p style={{ marginTop: "15px" }}>{message}</p>}
            </div>
          ) : (
            <div className="form-wrapper">
              <h2>SIGN IN</h2>
              <p className="form-subtext">Sign in with Email & Password</p>

              <div className="form-group">
                <label>Email or Mobile Number</label>
                <input type="text" placeholder="Enter Mobile Number or Email Address" />
              </div>

              <div className="form-group">
                <label>Password</label>
                <input type="password" placeholder="Password" />
              </div>

              <p className="forgot-password">Forgot Password?</p>

              <button className="primary-btn">SIGN IN</button>
            </div>
          )}
        </div>

        <div className="auth-panel brand-panel">
          <div className="brand-content">
            <h1 className="brand-title">RentMate</h1>
            <p className="brand-subtitle">
              {isSignUp
                ? "Already have an account? Sign in and continue exploring rentals."
                : "Sign up now and enjoy our site."}
            </p>

            <button
              className="outline-btn"
              onClick={() => setIsSignUp(!isSignUp)}
            >
              {isSignUp ? "SIGN IN" : "SIGN UP"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
